INSERT INTO patterns (slug, name, category, definition, when_to_use, why_it_works, intuition, invariant, strengths, weaknesses, recognition_signals, common_failure_modes, generalizations, time_complexity, space_complexity, time_reasoning, space_reasoning, status) 
VALUES ('two-pointers', 'Two Pointers', 'Array', 'Using two pointers to traverse an array from different directions or at different speeds.', 'When dealing with sorted arrays or finding pairs with specific properties.', 'By moving pointers based on comparison, we can eliminate impossible candidates efficiently.', 'Left pointer moves right, right pointer moves left.', 'Array must be sorted for the standard approach.', 'O(n) time, O(1) space for most problems.', 'Requires sorted input; not suitable for unsorted arrays without sorting first.', '["sorted array", "pair sum", "subarray", "palindrome"]'::jsonb, 'Forgetting to sort the array first; incorrect pointer movement logic.', 'Can be extended to three pointers for 3-sum problems.', 'O(n)', 'O(1)', 'Single pass with two pointers.', 'Only uses two pointer variables.', 'PUBLISHED');

INSERT INTO patterns (slug, name, category, definition, when_to_use, why_it_works, intuition, invariant, strengths, weaknesses, recognition_signals, common_failure_modes, generalizations, time_complexity, space_complexity, time_reasoning, space_reasoning, status) 
VALUES ('sliding-window', 'Sliding Window', 'Array', 'Maintaining a window of elements that slides through the array.', 'Finding subarrays/substrings with specific properties (sum, count, etc.).', 'By expanding and contracting the window, we avoid recomputing from scratch.', 'Window boundaries only move forward.', 'Elements must be positive for standard sum problems.', 'O(n) time, O(1) space.', 'Does not work with negative numbers for sum problems without modification.', '["subarray", "substring", "maximum", "minimum", "k elements"]'::jsonb, 'Incorrect window boundary updates; not handling edge cases.', 'Can use variable or fixed window size.', 'O(n)', 'O(1)', 'Each element visited at most twice.', 'Only stores window boundaries and current aggregate.', 'PUBLISHED');

INSERT INTO patterns (slug, name, category, definition, when_to_use, why_it_works, intuition, invariant, strengths, weaknesses, recognition_signals, common_failure_modes, generalizations, time_complexity, space_complexity, time_reasoning, space_reasoning, status) 
VALUES ('binary-search', 'Binary Search', 'Search', 'Divide and conquer search on sorted data by repeatedly halving the search space.', 'Finding an element in sorted array or finding boundary conditions.', 'Each comparison eliminates half of remaining candidates.', 'Search space is halved each iteration.', 'Requires sorted data.', 'O(log n) time, O(1) space.', 'Only works on sorted data; off-by-one errors common.', '["sorted", "find", "boundary", "first occurrence", "last occurrence"]'::jsonb, 'Infinite loops with while(left <= right); incorrect mid calculation.', 'Can find first/last occurrence, lower/upper bounds.', 'O(log n)', 'O(1)', 'Halving search space each step.', 'Constant space for indices.', 'PUBLISHED');

INSERT INTO patterns (slug, name, category, definition, when_to_use, why_it_works, intuition, invariant, strengths, weaknesses, recognition_signals, common_failure_modes, generalizations, time_complexity, space_complexity, time_reasoning, space_reasoning, status) 
VALUES ('prefix-sum', 'Prefix Sum', 'Array', 'Precomputing cumulative sums to answer range sum queries in O(1).', 'Multiple range sum queries on static array.', 'Range sum = prefix[r] - prefix[l-1].', 'Prefix array is monotonically increasing for positive numbers.', 'O(n) preprocessing, O(1) per query.', 'Does not handle updates efficiently.', '["range sum", "subarray sum", "multiple queries"]'::jsonb, 'Off-by-one errors in prefix indices; not handling l=0.', 'Can be extended to 2D prefix sums.', 'O(n) preprocessing', 'O(n) for prefix array', 'Single pass to build prefix array.', 'Stores n+1 prefix sums.', 'PUBLISHED');

INSERT INTO patterns (slug, name, category, definition, when_to_use, why_it_works, intuition, invariant, strengths, weaknesses, recognition_signals, common_failure_modes, generalizations, time_complexity, space_complexity, time_reasoning, space_reasoning, status) 
VALUES ('hash-map', 'Hash Map / Frequency Count', 'Hashing', 'Using hash map to store frequencies or indices for O(1) lookups.', 'Counting frequencies, finding duplicates, two-sum variants.', 'Hash map provides average O(1) insert/lookup.', 'Key-value pairs stored with hash function.', 'O(n) time, O(n) space.', 'Extra space overhead; hash collisions possible.', '["frequency", "count", "two-sum", "anagram", "duplicate"]'::jsonb, 'Using wrong key type; not handling missing keys.', 'Can use defaultdict or getOrDefault for cleaner code.', 'O(n)', 'O(n)', 'Single pass with hash map operations.', 'Stores up to n entries.', 'PUBLISHED');